import heapq
class Solution:
    def floodFill(self, n, m, sources):
        grid = [[0] * m for _ in range(n)]
        heap = []
        for r, c, col in sources:
            grid[r][c] = col
            heapq.heappush(heap, (0, -col, r, c))
        while heap:
            d, neg, r, c = heapq.heappop(heap)
            col = -neg
            if grid[r][c] != col:
                continue
            for nr, nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 0:
                    grid[nr][nc] = col
                    heapq.heappush(heap, (d + 1, -col, nr, nc))
        return grid

