class Solution {
    public int[][] floodFill(int n, int m, int[][] sources) {
        int[][] grid = new int[n][m];
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        for (int[] s : sources) {
            grid[s[0]][s[1]] = s[2];
            pq.add(new long[]{0, -(long)s[2], s[0], s[1]});
        }
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            int d = (int)top[0], col = (int)-top[1], r = (int)top[2], c = (int)top[3];
            if (grid[r][c] != col) continue;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 0) {
                    grid[nr][nc] = col;
                    pq.add(new long[]{d + 1, top[1], nr, nc});
                }
            }
        }
        return grid;
    }
}

