var floodFill = function(n, m, sources) {
    const grid = Array.from({length: n}, () => new Array(m).fill(0));
    const heap = [];
    const push = (item) => { heap.push(item); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (heap[p][0] < heap[i][0] || (heap[p][0] === heap[i][0] && heap[p][1] <= heap[i][1])) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const top = heap[0], last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            for (;;) { const l = 2*i+1, r = 2*i+2; let s = i;
                if (l < heap.length && (heap[l][0] < heap[s][0] || (heap[l][0] === heap[s][0] && heap[l][1] < heap[s][1]))) s = l;
                if (r < heap.length && (heap[r][0] < heap[s][0] || (heap[r][0] === heap[s][0] && heap[r][1] < heap[s][1]))) s = r;
                if (s === i) break; [heap[s], heap[i]] = [heap[i], heap[s]]; i = s; } }
        return top; };
    for (const [r, c, col] of sources) {
        grid[r][c] = col;
        push([0, -col, r, c]);
    }
    while (heap.length) {
        const [d, neg, r, c] = pop();
        const col = -neg;
        if (grid[r][c] !== col) continue;
        for (const [nr, nc] of [[r+1,c],[r-1,c],[r,c+1],[r,c-1]]) {
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] === 0) {
                grid[nr][nc] = col;
                push([d + 1, neg, nr, nc]);
            }
        }
    }
    return grid;
};
